		ac3: 0,
		eac3: 1,
		dts: 2,
		truehd: 3,
		alac: 4,
		flac: 5,
		wmav1: 6,
		wmav2: 7,
		wmapro: 8,
		wmalossless: 9,
		mp1: 10,
		mp2: 11,
		amrnb: 12,
		amrwb: 13,
		adpcm_ms: 14,
		adpcm_ima_wav: 15,
		adpcm_swf: 16,
		pcm_dvd: 17
