		["u8", 1, false],
		["s16", 2, false],
		["s32", 4, false],
		["f32", 4, false],
		null,
		["u8-planar", 1, true],
		["s16-planar", 2, true],
		["s32-planar", 4, true],
		["f32-planar", 4, true]
